mapper.select:
SELECT COUNT(*)
FROM USER_FITNESS_PROFILE
WHERE USER_ID = #{userId, jdbcType=NUMERIC}

mapper.insert:
INSERT INTO USER_FITNESS_PROFILE (
    USER_ID          /* 회원아이디 */
  , EXPERIENCE_CD    /* 운동경력코드 */
  , LEVEL_CD         /* 운동레벨코드 */
  , EQUIPMENT_CD     /* 보유장비코드 */
  , HEIGHT           /* 키 */
  , WEIGHT           /* 체중 */
  , GOAL_WEIGHT      /* 목표체중 */
  , GYM_ID           /* 헬스장아이디 */
  , SQUAT_YN         /* 스쿼트가능여부 */
  , BENCH_PRESS_YN   /* 벤치프레스가능여부 */
  , REG_DT           /* 등록일시 */
  , MOD_DT           /* 변경일시 */
) VALUES (
    #{userId, jdbcType=NUMERIC}
  , #{dto.experienceCd}
  , #{dto.levelCd}
  , #{dto.equipmentCd}
  , #{dto.height, jdbcType=NUMERIC}
  , #{dto.weight, jdbcType=NUMERIC}
  , #{dto.goalWeight, jdbcType=NUMERIC}
  , #{dto.gymId, jdbcType=NUMERIC}
  , NVL(#{dto.squatYn}, 'N')
  , NVL(#{dto.benchPressYn}, 'N')
  , SYSDATE
  , SYSDATE
)
